let language='te';try{language=localStorage.getItem('wedding-language-v2')==='en'?'en':'te'}catch{}
const toggle=document.getElementById('language'), music=document.getElementById('wed-music');
function applyLanguage(){document.documentElement.lang=language;document.querySelectorAll('[data-i18n]').forEach(el=>el.textContent=translations[el.dataset.i18n][language]);toggle.setAttribute('aria-pressed',String(language==='te'));toggle.setAttribute('aria-label',language==='te'?'Switch to English':'Switch to Telugu');document.getElementById('wed-open-btn').setAttribute('aria-label',language==='te'?'ఆహ్వానాన్ని తెరవండి':'Open invitation');document.getElementById('wed-back-to-session-2').setAttribute('aria-label',language==='te'?'వెనుకకు':'Back to couple');updateMusic();}
toggle.addEventListener('click',()=>{language=language==='en'?'te':'en';applyLanguage();try{localStorage.setItem('wedding-language-v2',language)}catch{}});
function show(id){document.querySelectorAll('.wed-session').forEach(el=>{const active=el.id===id;el.hidden=!active;el.classList.toggle('is-active',active);el.setAttribute('aria-hidden',String(!active));});window.scrollTo(0,0);const heading=document.querySelector('#'+id+' h1, #'+id+' h2');if(heading){heading.tabIndex=-1;heading.focus({preventScroll:true})}}
let opening=false;document.getElementById('wed-open-btn').addEventListener('click',()=>{if(opening)return;startMusic();opening=true;document.getElementById('wed-envelope').classList.add('is-open');setTimeout(()=>show('wed-session-2'),650)});
document.getElementById('wed-to-session-3').addEventListener('click',()=>show('wed-session-3'));
document.getElementById('wed-back-to-session-2').addEventListener('click',()=>show('wed-session-2'));
const musicIcons={"playing": "<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\" focusable=\"false\"><path d=\"M11 5 6 9H3v6h3l5 4V5Z\"/><path d=\"M15 8a6 6 0 0 1 0 8M18 5a10 10 0 0 1 0 14\"/></svg>", "paused": "<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\" focusable=\"false\"><path d=\"M11 5 6 9H3v6h3l5 4V5Z\"/><path d=\"m16 9 5 6m0-6-5 6\"/></svg>"};
function updateMusic() {
  document.querySelectorAll('.wed-mute-btn').forEach(button => {
    const state = music.paused ? 'paused' : 'playing';
    if (button.dataset.audioState !== state) {
      button.innerHTML = musicIcons[state];
      button.dataset.audioState = state;
    }
    const label = language === 'te'
      ? (music.paused ? 'సంగీతం వినండి' : 'సంగీతం ఆపండి')
      : (music.paused ? 'Play music' : 'Pause music');
    button.setAttribute('aria-label', label);
    button.setAttribute('title', label);
    button.setAttribute('aria-pressed', String(!music.paused));
  });
}
// Try audible playback by default, then retry within a real user gesture.
// The envelope click calls startMusic() synchronously before its animation.
let musicWanted = true;
function startMusic() {
  if (!musicWanted) return;
  music.muted = false;
  try {
    const playback = music.play();
    if (playback && typeof playback.then === 'function') {
      playback.then(updateMusic).catch(() => {
        // Autoplay may need a tap; keep the normal Play control available.
        updateMusic();
      });
    }
  } catch {
    updateMusic();
  }
}
document.querySelectorAll('.wed-mute-btn').forEach(button => {
  button.addEventListener('click', () => {
    if (music.paused) {
      musicWanted = true;
      startMusic();
    } else {
      // A deliberate pause stays paused during navigation and other taps.
      musicWanted = false;
      music.autoplay = false;
      music.pause();
    }
    updateMusic();
  });
});
function retryMusicOnGesture(event) {
  if (!event.isTrusted || event.target.closest('.wed-mute-btn')) return;
  if (event.type === 'keydown' && (event.repeat || event.ctrlKey || event.metaKey || event.altKey)) return;
  startMusic();
}
document.addEventListener('pointerdown', retryMusicOnGesture, {capture:true, passive:true});
document.addEventListener('click', retryMusicOnGesture, {capture:true});
document.addEventListener('keydown', retryMusicOnGesture, {capture:true});
['play','playing','pause','ended','error'].forEach(type => music.addEventListener(type, updateMusic));
applyLanguage();
startMusic();

// The invitation's Muhurtham starts at 4:00 AM India Standard Time.
const muhurthamStart = Date.parse('2026-11-15T04:00:00+05:30');
function getCountdownParts(now) {
  const remaining = Math.max(0, Math.ceil((muhurthamStart - now) / 1000));
  return {days: Math.floor(remaining / 86400), hours: Math.floor(remaining / 3600) % 24,
    minutes: Math.floor(remaining / 60) % 60, seconds: remaining % 60, complete: remaining === 0};
}
function updateCountdown() {
  const parts = getCountdownParts(Date.now());
  for (const unit of ['days', 'hours', 'minutes', 'seconds']) {
    document.getElementById('countdown-' + unit).textContent = String(parts[unit]).padStart(2, '0');
  }
  document.getElementById('countdown-complete').hidden = !parts.complete;
  return parts.complete;
}
if (!updateCountdown()) {
  const countdownInterval = setInterval(() => {
    if (updateCountdown()) clearInterval(countdownInterval);
  }, 1000);
}
